# Until now a credit's standing assumed every installment due so far had been paid on time. Those
# installments become one payment per credit, so balances do not change and real tracking starts today.
CARRIED_OVER_NOTE = "Pagos anteriores al registro de pagos (se asumen puntuales)"


def _carry_over_payments():
    today = datetime.now(ZoneInfo(current_app.config["TIMEZONE"])).date()
    credits = sa.table(
        'credits',
        sa.column('id', sa.Integer),
        sa.column('amount', sa.Numeric(14, 2)),
        sa.column('interest_rate', sa.Numeric(5, 2)),
        sa.column('term_months', sa.Integer),
        sa.column('issue_date', sa.Date),
    )
    payments = sa.table(
        'payments',
        sa.column('credit_id', sa.Integer),
        sa.column('amount', sa.Numeric(14, 2)),
        sa.column('paid_on', sa.Date),
        sa.column('note', sa.String),
    )
    rows = []
    for credit in op.get_bind().execute(sa.select(credits)):
        schedule = build_schedule(
            Decimal(str(credit.amount)), Decimal(str(credit.interest_rate)), credit.term_months, credit.issue_date
        )
        due = [installment for installment in schedule if installment.due_date <= today]
        if due:
            rows.append({
                'credit_id': credit.id,
                'amount': sum((installment.payment for installment in due), Decimal(0)),
                'paid_on': due[-1].due_date,
                'note': CARRIED_OVER_NOTE,
            })
    if rows:
        op.bulk_insert(payments, rows)


